// Дэд дугаар (эзэн 10-27 «дэд дугаарууд бас ашиглах»): «1 · 🚀 Эхлэх» доторх хуудас → «1.1 …», «1.2 …»;
// дэд бүлэг «4.1 Менежмент» → «4.1.1 Гэрээ». Нэрийг хуудасны sidebar_label (эсвэл H1)-ээс авна.
const fs = require("fs");
const path = require("path");

function labelOf(id) {
  for (const ext of [".md", ".mdx"]) {
    const file = path.join(__dirname, "docs", id + ext);
    if (!fs.existsSync(file)) continue;
    const src = fs.readFileSync(file, "utf8");
    const fm = /^---\r?\n([\s\S]*?)\r?\n---/.exec(src);
    const label = fm && /^sidebar_label:\s*(.+)$/m.exec(fm[1]);
    if (label) return label[1].trim().replace(/^["']|["']$/g, "");
    const h1 = /^# (.+)$/m.exec(src);
    if (h1) return h1[1].trim();
  }
  return id;
}

function number(items, prefix) {
  let i = 0;
  return items.map((it) => {
    if (typeof it === "string") return { type: "doc", id: it, label: `${prefix}.${++i} ${labelOf(it)}` };
    if (it.type === "category") {
      const n = `${prefix}.${++i}`;
      return { ...it, label: `${n} ${it.label}`, items: number(it.items, n) };
    }
    return it; // autogenerated — дугаарлахгүй
  });
}

for (const name of Object.keys(sidebars)) {
  sidebars[name] = sidebars[name].map((it) => {
    const m = it.type === "category" && /^(\d+)\. /.exec(it.label);
    return m ? { ...it, items: number(it.items, m[1]) } : it;
  });
}

module.exports = sidebars;
